[tool_call Write] {"file_path":"MerakiPages.Transport.ps1","content":"# MerakiPages.Transport.ps1 -- context construction and HTTP transport for the
# Cisco Meraki Dashboard API v1. Auto-redirect is disabled so the module can
# decide per-target whether the Authorization header survives a shard redirect
# (api.meraki.com 302s GETs to dashboard shards; generic clients drop auth).

Set-StrictMode -Version Latest

$script:MerakiHttpHandler = [System.Net.Http.HttpClientHandler]::new()
$script:MerakiHttpHandler.AllowAutoRedirect = $false
$script:MerakiHttpClient = [System.Net.Http.HttpClient]::new($script:MerakiHttpHandler)

function New-MerakiContext {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$BaseUri,
        [Parameter(Mandatory)][string]$ApiKey,
        [string[]]$TrustedHosts = @('.meraki.com', '.meraki.ca', '.meraki.cn', '.meraki.in', '.gov-meraki.com'),
        [int]$RetryLimit = 3,
        [scriptblock]$SleepAction = { param($seconds) Start-Sleep -Seconds $seconds }
    )

    return [pscustomobject]@{
        BaseUri      = $BaseUri.TrimEnd('/')
        [REDACTED_SECRET]
        TrustedHosts = @($TrustedHosts)
        RetryLimit   = $RetryLimit
        SleepAction  = $SleepAction
    }
}

function Protect-MerakiSecret {
    param(
        [AllowEmptyString()][string]$Value,
        [Parameter(Mandatory)]$Context
    )
    if ([string]::IsNullOrEmpty($Value) -or [string]::IsNullOrEmpty([string]$Context.ApiKey)) {
        return $Value
    }
    # string.Replace(string, string) is ordinal
    return $Value.Replace([string]$Context.ApiKey, '[REDACTED]')
}

function Test-MerakiTrustedUri {
    param(
        [Parameter(Mandatory)][uri]$Uri,
        [Parameter(Mandatory)]$Context
    )

    # Uri.Port is the effective port (default filled in), so host:port compares
    # work even when one side spells out a scheme-default port and the other
    # omits it (Uri.Authority strips default ports).
    $effective = '{0}:{1}' -f $Uri.Host, $Uri.Port

    # The authority the user pointed the context at is inherently trusted:
    # pagination Link URLs come back absolute on the same dashboard host.
    $base = [uri]$Context.BaseUri
    if ($base.IsAbsoluteUri) {
        $baseEffective = '{0}:{1}' -f $base.Host, $base.Port
        if ([string]::Equals($baseEffective, $effective, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }

    foreach ($entry in @($Context.TrustedHosts)) {
        $trusted = ([string]$entry).Trim()
        if ($trusted.Length -eq 0) { continue }
        if ($trusted.StartsWith('.')) {
            # Meraki host-family suffix (e.g. .meraki.com matches n123.meraki.com)
            if ($Uri.Host.EndsWith($trusted, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $true
            }
        }
        else {
            # Explicitly injected host or host:port authority
            if ([string]::Equals($trusted, $Uri.Host, [System.StringComparison]::OrdinalIgnoreCase) -or
                [string]::Equals($trusted, $Uri.Authority, [System.StringComparison]::OrdinalIgnoreCase) -or
                [string]::Equals($trusted, $effective, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $true
            }
        }
    }

    return $false
}

function Invoke-MerakiApi {
    [CmdletBinding(DefaultParameterSetName = 'Path')]
    param(
        [Parameter(Mandatory)]$Context,
        [Parameter(Mandatory, ParameterSetName = 'Path')][string]$Path,
        [Parameter(Mandatory, ParameterSetName = 'Uri')][string]$Uri
    )

    if ($PSCmdlet.ParameterSetName -ceq 'Path') {
        $relative = if ($Path.StartsWith('/')) { $Path } else { '/' + $Path }
        $target = [uri]([string]$Context.BaseUri + $relative)
        # Requests against the configured base endpoint always authenticate.
        $sendAuth = $true
    }
    else {
        $target = [uri]$Uri
        # An arbitrary absolute URL (e.g. a pagination Link) only receives the
        # key when its authority is trusted.
        $sendAuth = Test-MerakiTrustedUri -Uri $target -Context $Context
    }

    $retries = 0
    $redirects = 0

    while ($true) {
        $request = [System.Net.Http.HttpRequestMessage]::new([System.Net.Http.HttpMethod]::Get, $target)
        if ($sendAuth) {
            $null = $request.Headers.TryAddWithoutValidation('Authorization', ('Bearer {0}' -f [string]$Context.ApiKey))
        }
        $response = $script:MerakiHttpClient.Send($request)
        try {
            $status = [int]$response.StatusCode

            if ($status -in 301, 302, 303, 307, 308) {
                if ($redirects -ge 10) {
                    throw (Protect-MerakiSecret -Value ('Meraki API request failed: too many redirects (last status {0})' -f $status) -Context $Context)
                }
                $location = $response.Headers.Location
                if ($null -eq $location) {
                    throw (Protect-MerakiSecret -Value ('Meraki API request failed with status {0}: redirect without a Location header' -f $status) -Context $Context)
                }
                $target = [uri]::new($target, $location)
                $sendAuth = Test-MerakiTrustedUri -Uri $target -Context $Context
                $redirects++
                continue
            }

            if ($status -eq 429 -and $retries -lt [int]$Context.RetryLimit) {
                $waitSeconds = 1
                $retryAfterValues = $null
                if ($response.Headers.TryGetValues('Retry-After', [ref]$retryAfterValues)) {
                    $waitSeconds = [int](@($retryAfterValues)[0])
                }
                $null = & $Context.SleepAction $waitSeconds
                $retries++
                continue
            }

            $bodyText = $response.Content.ReadAsStringAsync().GetAwaiter().GetResult()

            if ($status -lt 200 -or $status -ge 300) {
                $messages = @()
                try {
                    $envelope = ConvertFrom-Json -InputObject $bodyText -ErrorAction Stop
                    if ($null -ne $envelope -and $null -ne $envelope.PSObject.Properties['errors']) {
                        $messages = @($envelope.errors | ForEach-Object { [string]$_ })
                    }
                }
                catch { }
                $message = 'Meraki API request failed with status {0}' -f $status
                if ($messages.Count -gt 0) {
                    $message = $message + ': ' + ($messages -join '; ')
                }
                throw (Protect-MerakiSecret -Value $message -Context $Context)
            }

            $body = $null
            if (-not [string]::IsNullOrWhiteSpace($bodyText)) {
                $body = ConvertFrom-Json -InputObject $bodyText -NoEnumerate
            }

            $linkHeader = ''
            $linkValues = $null
            if ($response.Headers.TryGetValues('Link', [ref]$linkValues)) {
                $linkHeader = @($linkValues) -join ', '
            }

            return [pscustomobject]@{
                StatusCode = $status
                Body       = $body
                LinkHeader = $linkHeader
            }
        }
        finally {
            $response.Dispose()
        }
    }
}
"}

[tool_call Write] {"file_path":"MerakiPages.Paging.ps1","content":"# MerakiPages.Paging.ps1 -- RFC 5988 Link header parsing and page walking for
# the Meraki Dashboard API v1. The rel=next URL is followed verbatim; query
# strings are never rebuilt.

Set-StrictMode -Version Latest

function ConvertFrom-LinkHeader {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Value
    )

    $links = [hashtable]::new([System.StringComparer]::Ordinal)
    if ([string]::IsNullOrWhiteSpace($Value)) {
        return $links
    }

    # Meraki emits both rel=next and rel="next"; accept either form.
    $pattern = '<(?<url>[^>]+)>\s*;\s*rel\s*=\s*"?(?<rel>[^";,\s]+)"?'
    foreach ($match in [regex]::Matches($Value, $pattern)) {
        $links[$match.Groups['rel'].Value] = $match.Groups['url'].Value
    }
    return $links
}

function Get-MerakiPaged {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Context,
        [Parameter(Mandatory)][string]$Path,
        [int]$PerPage
    )

    $firstPath = $Path
    if ($PSBoundParameters.ContainsKey('PerPage')) {
        $separator = if ($Path.Contains('?')) { '&' } else { '?' }
        $firstPath = '{0}{1}perPage={2}' -f $Path, $separator, $PerPage
    }

    $items = [System.Collections.Generic.List[object]]::new()
    $response = Invoke-MerakiApi -Context $Context -Path $firstPath
    while ($true) {
        if ($null -ne $response.Body) {
            foreach ($item in @($response.Body)) {
                $items.Add($item)
            }
        }
        $links = ConvertFrom-LinkHeader -Value ([string]$response.LinkHeader)
        if (-not $links.ContainsKey('next')) {
            break
        }
        $response = Invoke-MerakiApi -Context $Context -Uri $links['next']
    }

    return ,$items.ToArray()
}
"}

[tool_call Write] {"file_path":"MerakiPages.Inventory.ps1","content":"# MerakiPages.Inventory.ps1 -- organization inventory collection and the
# byte-stable JSON serialization the CMDB diff import depends on. Ordering and
# key order are pinned by docs/contract.json; all sorts are ordinal.

Set-StrictMode -Version Latest

function Get-MerakiInventory {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Context,
        [Parameter(Mandatory)][string]$OrganizationId,
        [int]$PerPage
    )

    $pagedArgs = @{}
    if ($PSBoundParameters.ContainsKey('PerPage')) {
        $pagedArgs['PerPage'] = $PerPage
    }

    $networks = Get-MerakiPaged -Context $Context -Path ('/organizations/{0}/networks' -f $OrganizationId) @pagedArgs
    $devices = Get-MerakiPaged -Context $Context -Path ('/organizations/{0}/devices' -f $OrganizationId) @pagedArgs

    return [pscustomobject]@{
        OrganizationId = $OrganizationId
        Networks       = @($networks)
        Devices        = @($devices)
    }
}

function Get-MerakiField {
    param(
        [Parameter(Mandatory)]$Object,
        [Parameter(Mandatory)][string]$Name
    )
    $property = $Object.PSObject.Properties[$Name]
    if ($null -ne $property) { return $property.Value }
    return $null
}

function ConvertTo-MerakiJsonString {
    param([AllowNull()][object]$Value)

    if ($null -eq $Value) { return 'null' }
    $text = [string]$Value
    $builder = [System.Text.StringBuilder]::new()
    $null = $builder.Append('"')
    foreach ($ch in $text.ToCharArray()) {
        switch ($ch) {
            '"' { $null = $builder.Append('\"') }
            '\' { $null = $builder.Append('\\') }
            default {
                $code = [int][char]$ch
                if ($code -lt 0x20) {
                    $null = $builder.Append(('\u{0:x4}' -f $code))
                }
                else {
                    $null = $builder.Append($ch)
                }
            }
        }
    }
    $null = $builder.Append('"')
    return $builder.ToString()
}

function ConvertTo-MerakiInventoryJson {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Inventory
    )

    $networks = [System.Collections.Generic.List[object]]::new()
    foreach ($network in @($Inventory.Networks)) { $networks.Add($network) }
    $networks.Sort([System.Comparison[object]] {
            param($a, $b)
            [string]::CompareOrdinal([string](Get-MerakiField -Object $a -Name 'id'), [string](Get-MerakiField -Object $b -Name 'id'))
        })

    $devices = [System.Collections.Generic.List[object]]::new()
    foreach ($device in @($Inventory.Devices)) { $devices.Add($device) }
    $devices.Sort([System.Comparison[object]] {
            param($a, $b)
            [string]::CompareOrdinal([string](Get-MerakiField -Object $a -Name 'serial'), [string](Get-MerakiField -Object $b -Name 'serial'))
        })

    $builder = [System.Text.StringBuilder]::new()
    $null = $builder.Append('{"organizationId":')
    $null = $builder.Append((ConvertTo-MerakiJsonString -Value $Inventory.OrganizationId))
    $null = $builder.Append(',"networks":[')
    for ($i = 0; $i -lt $networks.Count; $i++) {
        if ($i -gt 0) { $null = $builder.Append(',') }
        $network = $networks[$i]
        $productTypes = [string[]]@(@(Get-MerakiField -Object $network -Name 'productTypes') | ForEach-Object { [string]$_ })
        [array]::Sort($productTypes, [System.StringComparer]::Ordinal)
        $null = $builder.Append('{"id":')
        $null = $builder.Append((ConvertTo-MerakiJsonString -Value (Get-MerakiField -Object $network -Name 'id')))
        $null = $builder.Append(',"name":')
        $null = $builder.Append((ConvertTo-MerakiJsonString -Value (Get-MerakiField -Object $network -Name 'name')))
        $null = $builder.Append(',"productTypes":[')
        for ($j = 0; $j -lt $productTypes.Length; $j++) {
            if ($j -gt 0) { $null = $builder.Append(',') }
            $null = $builder.Append((ConvertTo-MerakiJsonString -Value $productTypes[$j]))
        }
        $null = $builder.Append(']}')
    }
    $null = $builder.Append('],"devices":[')
    for ($i = 0; $i -lt $devices.Count; $i++) {
        if ($i -gt 0) { $null = $builder.Append(',') }
        $device = $devices[$i]
        $null = $builder.Append('{"serial":')
        $null = $builder.Append((ConvertTo-MerakiJsonString -Value (Get-MerakiField -Object $device -Name 'serial')))
        $null = $builder.Append(',"name":')
        $null = $builder.Append((ConvertTo-MerakiJsonString -Value (Get-MerakiField -Object $device -Name 'name')))
        $null = $builder.Append(',"model":')
        $null = $builder.Append((ConvertTo-MerakiJsonString -Value (Get-MerakiField -Object $device -Name 'model')))
        $null = $builder.Append(',"networkId":')
        $null = $builder.Append((ConvertTo-MerakiJsonString -Value (Get-MerakiField -Object $device -Name 'networkId')))
        $null = $builder.Append(',"productType":')
        $null = $builder.Append((ConvertTo-MerakiJsonString -Value (Get-MerakiField -Object $device -Name 'productType')))
        $null = $builder.Append('}')
    }
    $null = $builder.Append(']}')

    return $builder.ToString()
}
"}
