function Start-FakeServer {
    $port = Get-FreePort
    $state = [hashtable]::Synchronized(@{
        Requests = [System.Collections.ArrayList]::Synchronized([System.Collections.ArrayList]::new())
        Routes   = [hashtable]::Synchronized(@{})
    })
    $listener = [System.Net.HttpListener]::new()
    $listener.Prefixes.Add("http://127.0.0.1:$port/")
    $listener.Start()
    $job = Start-ThreadJob -ScriptBlock {
        param($listener, $state)
        while ($listener.IsListening) {
            try { $ctx = $listener.GetContext() } catch { break }
            $req = $ctx.Request
            $null = $state.Requests.Add(@{
                Path          = $req.Url.AbsolutePath
                Authorization = $req.Headers['Authorization']
            })
            $key = '{0} {1}' -f $req.HttpMethod, $req.Url.AbsolutePath
            $queue = $state.Routes[$key]
            if ($null -eq $queue -or $queue.Count -eq 0) {
                $resp = @{ Status = 500; Body = '{"errors":["unexpected"]}'; Headers = @{} }
            } else {
                $resp = $queue[0]; $queue.RemoveAt(0)
            }
            $out = $ctx.Response
            $out.StatusCode = $resp.Status
            foreach ($name in $resp.Headers.Keys) {
                if ($name -eq 'Location') { $out.RedirectLocation = [string]$resp.Headers[$name] }
                else { $out.Headers.Add($name, [string]$resp.Headers[$name]) }
            }
            $bytes = [System.Text.Encoding]::UTF8.GetBytes([string]$resp.Body)
            $out.ContentType = 'application/json'
            $out.ContentLength64 = $bytes.Length
            $out.OutputStream.Write($bytes, 0, $bytes.Length)
            $out.Close()
        }
    } -ArgumentList $listener, $state
    [pscustomobject]@{ Listener = $listener; Job = $job; State = $state; Port = $port; BaseUri = "http://127.0.0.1:$port/api/v1" }
}

function Add-Route {
    param($Server, [string]$Key, [int]$Status, [string]$Body, [hashtable]$Headers = @{})
    if (-not $Server.State.Routes.ContainsKey($Key)) {
        $Server.State.Routes[$Key] = [System.Collections.ArrayList]::Synchronized([System.Collections.ArrayList]::new())
    }
    $null = $Server.State.Routes[$Key].Add(@{ Status = $Status; Body = $Body; Headers = $Headers })
}

Import-Module (Join-Path $PSScriptRoot 'MerakiPages.psm1') -Force

$fail = 0
$serverA = Start-FakeServer
$serverX = Start-FakeServer
try {
    $sleepEmitter = { param($seconds) "SLEEP-NOISE-$seconds" }
    $ctx = New-MerakiContext -BaseUri $serverA.BaseUri -ApiKey $ApiKey -SleepAction $sleepEmitter

    # 1. Error envelope echoing the key must be redacted
    Add-Route $serverA 'GET /api/v1/echo' 404 ('{"errors":["server echoed ' + $ApiKey + '"]}')
    $msg = ''
    try { $null = Invoke-MerakiApi -Context $ctx -Path '/echo' } catch { $msg = $_.Exception.Message }
    $leak = $msg.Contains($ApiKey)
    Write-Output ("1 ErrorContainsApiKey:{0} msg:{1}" -f $leak, $msg)
    if ($leak -or ($msg -notmatch '404')) { $fail++ }

    # 2. Explicit host:port trust entry with a scheme-default port
    $trustCheck = & (Get-Module MerakiPages) {
        param($c) Test-MerakiTrustedUri -Uri ([uri]'https://example.test:443/next') -Context $c
    } (New-MerakiContext -BaseUri 'https://api.meraki.com/api/v1' -ApiKey 'k' -TrustedHosts @('example.test:443'))
    Write-Output ("2 DefaultPortAuthorityTrusted:{0}" -f $trustCheck)
    if (-not $trustCheck) { $fail++ }

    # 2b. Explicit host:port entry still matches when the URL omits the port
    $trustCheck2 = & (Get-Module MerakiPages) {
        param($c) Test-MerakiTrustedUri -Uri ([uri]'https://example.test/next') -Context $c
    } (New-MerakiContext -BaseUri 'https://api.meraki.com/api/v1' -ApiKey 'k' -TrustedHosts @('example.test:443'))
    Write-Output ("2b ImplicitPortTrusted:{0}" -f $trustCheck2)
    if (-not $trustCheck2) { $fail++ }

    # 3. Initial absolute -Uri to an untrusted host must NOT send the key
    Add-Route $serverX 'GET /api/v1/abs' 200 '[]'
    $ctxDefaultTrust = New-MerakiContext -BaseUri $serverA.BaseUri -ApiKey $ApiKey
    $null = Invoke-MerakiApi -Context $ctxDefaultTrust -Uri ("http://127.0.0.1:$($serverX.Port)/api/v1/abs")
    $absAuth = @($serverX.State.Requests | Where-Object { $_.Path -eq '/api/v1/abs' })[0].Authorization
    Write-Output ("3 AbsoluteUntrustedAuthorization:'{0}'" -f $absAuth)
    if (-not [string]::IsNullOrEmpty($absAuth)) { $fail++ }

    # 3b. Absolute -Uri on the BaseUri authority (pagination next link) keeps auth
    Add-Route $serverA 'GET /api/v1/abs2' 200 '[]'
    $null = Invoke-MerakiApi -Context $ctxDefaultTrust -Uri ("$($serverA.BaseUri)/../abs2".Replace('/api/v1/../', '/api/v1/'))
    $abs2Auth = @($serverA.State.Requests | Where-Object { $_.Path -eq '/api/v1/abs2' })[0].Authorization
    Write-Output ("3b BaseAuthorityAbsoluteAuthorization:'{0}'" -f $abs2Auth)
    if ($abs2Auth -cne "Bearer $ApiKey") { $fail++ }

    # 4. Emitting SleepAction must not pollute the return: exactly one object
    Add-Route $serverA 'GET /api/v1/rl' 429 '{"errors":["API rate limit exceeded for organization"]}' @{ 'Retry-After' = '3' }
    Add-Route $serverA 'GET /api/v1/rl' 200 '[{"serial":"OK-1"}]'
    $result = Invoke-MerakiApi -Context $ctx -Path '/rl'
    $types = @($result | ForEach-Object { $_.GetType().Name }) -join ','
    Write-Output ("4 ReturnCount:{0} Types:{1} Status:{2}" -f @($result).Count, $types, @($result)[0].StatusCode)
    if (@($result).Count -ne 1 -or $types -cne 'PSCustomObject') { $fail++ }

    # 5. Untrusted host suffix probe still trusted for real Meraki families
    $sfx = & (Get-Module MerakiPages) {
        param($c) (Test-MerakiTrustedUri -Uri ([uri]'https://n123.meraki.com/x') -Context $c), (Test-MerakiTrustedUri -Uri ([uri]'https://evil.example/x') -Context $c)
    } (New-MerakiContext -BaseUri 'https://api.meraki.com/api/v1' -ApiKey 'k')
    Write-Output ("5 MerakiSuffixTrusted:{0} EvilTrusted:{1}" -f @($sfx)[0], @($sfx)[1])
    if (-not @($sfx)[0] -or @($sfx)[1]) { $fail++ }

    if ($fail -eq 0) { Write-Output 'PROBES OK' ; exit 0 } else { Write-Output "PROBES FAILED: $fail"; exit 1 }
}
finally {
    foreach ($server in @($serverA, $serverX)) {
        try { $server.Listener.Stop(); $server.Listener.Close() } catch { }
        try { $null = Wait-Job -Job $server.Job -Timeout 5; Remove-Job -Job $server.Job -Force } catch { }
    }
}
